type Section = 'cases' | 'informants' | 'intel' | 'tasks'
type CaseStatus = 'В ожидании' | 'В работе' | 'Приостановлено' | 'Закрыто'
type Person = { id: number | string; name: string; callsign: string; initials: string; role?: string }
type CaseFile = {
  id: string; dbId?: string; title: string; status: CaseStatus; priority: 'Критический' | 'Высокий' | 'Средний' | 'Низкий'
  lead: string; members: string[]; created: string; summary: string; location: string
  suspects: string[]; victims: string[]; witnesses: string[]; evidence: string[]; theories: string[]; report?: string
  boardLayout?: Record<string, { x: number; y: number }>
  boardCards?: BoardCard[]; boardLinks?: BoardLink[]
  memberIds?: string[]
  isRestricted?: boolean; allowedUserIds?: string[]; locked?: boolean
}
type TaskStatus = 'OPEN' | 'IN_PROGRESS' | 'DONE' | 'FROZEN'
type Task = { id: number | string; title: string; due: string; assignee?: string; assigneeId?: string; done: boolean; status?: TaskStatus; report?: string; tag: string; caseDbId?: string; caseNumber?: string }
type Informant = { id: string; alias: string; reliability: number; area: string; status: string; note: string; last: string; notes?: string; regCode?: string; photoUrl?: string; realName?: string }
type AspectKey = 'suspects'|'victims'|'witnesses'|'evidence'|'theories'
const isPersonKind=(kind:string)=>['suspects','victims','witnesses'].includes(kind)
type BoardCard={id:string;kind:AspectKey|'note';title:string;body?:string;regCode?:string;photoUrl?:string;x:number;y:number}
type BoardLink={id:string;from:string;to:string}
const makeId=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}-${Math.random().toString(36).slice(2,6)}`

